insert into public.site_settings (id, studio_statement, intro_enabled, contact_email) values (1, 'Alpha Studios is a studio of young engineers building AI-powered tools, native apps and the APIs behind them. We care about careful work, honest results and giving builders the credit they earn.', true, 'hello@alphastudios.example') on conflict (id) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, age, location, open_to, languages, interests, experience, education) values ('hari-rudran-sunil', 'Hari Rudran Sunil', 'Founder, AI and ML engineer', 'Builds intelligent software and the studio that ships it. Believes young builders deserve real backing.', 'hari-rudran', '{"github":"https://example.com/hari-rudran-sunil/github","linkedin":"https://example.com/hari-rudran-sunil/linkedin","instagram":"https://example.com/hari-rudran-sunil/instagram"}'::jsonb, '{"version":1,"options":{"head":3,"skin":3,"eyes":0,"brows":3,"nose":1,"mouth":1,"hair":7,"hairColor":1,"facialHair":3,"glasses":0,"glassesColor":0,"earrings":0,"chain":0,"outfit":1,"outfitColor":2}}'::jsonb, 'KINGHRS', '', '[{"name":"Machine learning","level":5},{"name":"Python","level":5},{"name":"System design","level":4},{"name":"Swift","level":3}]'::jsonb, '', '', 'Interstellar', 20, 'Kerala, India', 'Mentoring, research collaborations', array['English', 'Malayalam', 'Hindi']::text[], array['Chess', 'Astronomy', 'Late-night coding']::text[], '[{"title":"Founder","org":"Alpha Studios","from":"2025","to":"Now","note":"Leads the studio, the product direction and the AI work."},{"title":"Machine learning intern","org":"Example Labs","from":"2024","to":"2025","note":"Trained and shipped a vision model into a mobile app."}]'::jsonb, '[{"school":"Example Institute of Technology","field":"B.Tech, AI and ML","from":"2023","to":"Now"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, age, location, open_to, languages, interests, experience, education) values ('riya-suresh', 'Riya Suresh', 'Bioinformatics', 'Turns biological data into answers, and keeps the science in our products honest.', 'riya-suresh', '{"github":"https://example.com/riya-suresh/github","linkedin":"https://example.com/riya-suresh/linkedin","instagram":"https://example.com/riya-suresh/instagram"}'::jsonb, '{"version":1,"options":{"head":0,"skin":2,"eyes":1,"brows":1,"nose":0,"mouth":1,"hair":4,"hairColor":1,"facialHair":0,"glasses":1,"glassesColor":0,"earrings":1,"chain":0,"outfit":1,"outfitColor":7}}'::jsonb, 'The brain', '', '[{"name":"Bioinformatics","level":5},{"name":"Python","level":4},{"name":"Statistics","level":5},{"name":"Data visualisation","level":4}]'::jsonb, '', '', 'Breaking Bad', 20, 'Kochi, India', 'Science reviews, study groups', array['English', 'Malayalam']::text[], array['Genomics', 'Badminton', 'Documentaries']::text[], '[{"title":"Research assistant","org":"Example Genomics Lab","from":"2025","to":"Now","note":"Cleans and analyses sequencing data for a student research group."}]'::jsonb, '[{"school":"Example University","field":"B.Sc. Bioinformatics","from":"2023","to":"Now"}]'::jsonb) on conflict (slug) do nothing;
