insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, age, location, open_to, languages, interests, experience, education) values ('eldho-gibi', 'Eldho Gibi', 'AI and ML engineer', 'Connects the models to the real world with fast, dependable data pipelines and APIs.', 'eldho-gibi', '{"github":"https://example.com/eldho-gibi/github","linkedin":"https://example.com/eldho-gibi/linkedin","instagram":"https://example.com/eldho-gibi/instagram"}'::jsonb, '{"version":1,"options":{"head":4,"skin":3,"eyes":2,"brows":0,"nose":3,"mouth":4,"hair":3,"hairColor":0,"facialHair":1,"glasses":0,"glassesColor":0,"earrings":0,"chain":0,"outfit":0,"outfitColor":4}}'::jsonb, 'Babu', '', '[{"name":"Backend","level":5},{"name":"FastAPI","level":5},{"name":"Data pipelines","level":4},{"name":"Swift","level":4}]'::jsonb, '', '', 'GTA VI', 20, 'Ernakulam, India', 'Pair programming, open source', array['English', 'Malayalam']::text[], array['Cricket', 'Open source', 'Street food']::text[], '[{"title":"Backend and ML engineer","org":"Alpha Studios","from":"2025","to":"Now","note":"Owns the services that serve the models and the Velocity engine."}]'::jsonb, '[{"school":"Example Institute of Technology","field":"B.Tech, AI and ML","from":"2023","to":"Now"}]'::jsonb) on conflict (slug) do nothing;
insert into public.members (slug, name, role_title, bio, github_username, links, avatar, codename, tagline, skills, currently, fun_fact, pop_pick, age, location, open_to, languages, interests, experience, education) values ('rohan', 'Rohan', 'Chartered Accountancy', 'Keeps the studio''s numbers, contracts and licences in order so the builders can build.', 'rohan-ca', '{"github":"https://example.com/rohan/github","linkedin":"https://example.com/rohan/linkedin","instagram":"https://example.com/rohan/instagram"}'::jsonb, '{"version":1,"options":{"head":1,"skin":1,"eyes":0,"brows":2,"nose":1,"mouth":2,"hair":1,"hairColor":0,"facialHair":0,"glasses":2,"glassesColor":4,"earrings":0,"chain":0,"outfit":1,"outfitColor":1}}'::jsonb, 'The brain', '', '[{"name":"Accounting","level":5},{"name":"Financial planning","level":4},{"name":"Licensing","level":4},{"name":"Spreadsheets","level":5}]'::jsonb, '', '', 'Money Heist', 20, 'Kerala, India', 'Finance guidance for student founders', array['English', 'Malayalam', 'Hindi']::text[], array['Markets', 'Football', 'Strategy games']::text[], '[{"title":"Finance and operations","org":"Alpha Studios","from":"2025","to":"Now","note":"Handles budgets, licensing and the books."}]'::jsonb, '[{"school":"Institute of Chartered Accountants (example)","field":"CA Intermediate","from":"2023","to":"Now"}]'::jsonb) on conflict (slug) do nothing;
insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('bioscanner', 'Bioscanner', 'Point your camera at a plant, insect or sample and get an identification with a clear confidence score.', 'Bioscanner began in a biology lab where students spent hours matching specimens to reference books. It identifies plants, insects and microscope samples from a single photo, shows how sure it is, and explains what it saw so a person can check the answer. The recognition models run on our own servers behind a FastAPI service, with an iPhone app, an Android app and a web version for the lab bench. It is in open beta while we gather more labelled images from classrooms and field trips.', 'beta', array['ios', 'android', 'web']::text[], array['Python', 'PyTorch', 'FastAPI', 'Swift', 'React']::text[], '{"github":"https://example.com/alpha-studios/bioscanner","demo":"https://example.com/bioscanner/demo"}'::jsonb, 'alpha-studios-demo/bioscanner', true, '[{"src":"screens/bioscanner-iphone-1.png","alt":"Bioscanner result screen with a confidence score","device":"iphone"},{"src":"screens/bioscanner-browser-1.png","alt":"Bioscanner web upload and results","device":"browser"},{"src":"screens/bioscanner-android-1.png","alt":"Bioscanner history on Android","device":"android"}]'::jsonb) on conflict (slug) do nothing;
insert into public.projects (slug, name, summary, story, status, platforms, tech, links, repo, featured, screenshots) values ('velocity', 'Velocity', 'A native macOS download manager that splits files into parallel streams, resumes broken downloads and stays quietly in the menu bar.', 'Large downloads on a Mac should not be a gamble. Velocity breaks every file into parallel streams, checks each piece as it arrives and resumes exactly where a connection dropped, even after a restart. It is written natively in Swift and SwiftUI, so it opens instantly, sips battery and looks at home in the menu bar. A clean queue, bandwidth limits and a scheduler keep big transfers out of the way of your work. Hari designed the architecture, Eldho built the transfer engine and Rohan set up licensing.', 'live', array['macos']::text[], array['Swift', 'SwiftUI', 'Network framework', 'Core Data']::text[], '{"appStore":"https://example.com/velocity/app-store","github":"https://example.com/alpha-studios/velocity"}'::jsonb, 'alpha-studios-demo/velocity', true, '[{"src":"screens/velocity-mac-1.png","alt":"Velocity download queue on Mac","device":"mac"},{"src":"screens/velocity-mac-2.png","alt":"Velocity transfer details","device":"mac"},{"src":"screens/velocity-mac-3.png","alt":"Velocity scheduler settings","device":"mac"}]'::jsonb) on conflict (slug) do nothing;
